import{z as i,x as A,o as E,c as d,q as l,j as s,D as o,d as t,s as B,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"布谷鸟过滤器","description":"","frontmatter":{"title":"布谷鸟过滤器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cuckoo-filter.md","filePath":"cs/cuckoo-filter.md","lastUpdated":1791413859000}'),p={name:"cs/cuckoo-filter.md"};function c(h,a,m,u,C,f){const r=A("Mermaid");return E(),d("div",null,[a[2]||(a[2]=l('<h1 id="布谷鸟过滤器" tabindex="-1">布谷鸟过滤器 <a class="header-anchor" href="#布谷鸟过滤器" aria-label="Permalink to &quot;布谷鸟过滤器&quot;">​</a></h1><div class="epigraph"><p>不存键，只存指纹；每个指纹两个候选桶，插入像布谷散列那样踢。删除可以摘掉指纹，Bloom 做不到。</p><footer>—— 据 Fan, Andersen, Kaminsky and Mitzenmacher, Cuckoo Filter: Practically Better Than Bloom, CoNEXT 2014；Pagh and Rodler, Cuckoo Hashing 整理</footer></div><p><a href="/cs/hyperloglog">上一课</a> 不支持成员。<a href="/cs/bloom-filter">布隆</a> 假阳性、无删除（标准版）。<a href="/cs/robin-cuckoo">布谷散列</a> 存真键。本课不估基数。缺口是 cuckoo filter：桶里是指纹，用 <code>h1</code> 与 <code>h1 xor hash(fp)</code> 定位。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>近似集：空间近 Bloom，但要删除、要查失败时仍紧凑。指纹 \\(\\mathrm{fp}(x)\\) 短，假阳性约桶负载与指纹位数决定。插入：两桶有空则放；否则踢走一个指纹到另一桶（由 fp 反推另一下标）。踢链过长则扩容或失败。缺口是<strong>用指纹的异或关系代替存键</strong>，使踢人仍能找到另一巢。</p><p><span class="marginnote">指纹就是键的一小段哈希（比如 8 位）。妙处在异或配对：两个候选桶的下标互为&quot;对方 xor 指纹&quot;，于是手里只有指纹也能算出另一巢——这就是&quot;不存键也能踢人搬家&quot;的全部机关。</span></p><p><span class="marginnote">Fan et al., <em>CoNEXT</em>, 2014。每桶（bucket）存多个指纹，提高占用率。Pagh–Rodler 布谷给踢人算法。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>查找：检查两桶是否含 fp。删除：找到则删一个匹配指纹——可能误删同指纹的另一键，合同是近似。计数器 Bloom 可删但更费空间。</p><p><span class="marginnote">初学者容易以为&quot;删除是精确的&quot;。过滤器只认指纹：同一桶里两枚相同指纹可能来自不同键，删一次摘掉一枚，但分不清摘的是谁的——所以合同是近似，应用层必须保证&quot;只删确实插入过的键&quot;。</span></p>',10)),(E(),s(n,null,{default:o(()=>[B(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22x%22%5D%20--%3E%20FP%5B%22%E6%8C%87%E7%BA%B9%20fp%22%5D%0A%20%20FP%20--%3E%20B1%5B%22%E6%A1%B6%20h1(x)%22%5D%0A%20%20FP%20--%3E%20B2%5B%22%E6%A1%B6%20h1%20xor%20hash(fp)%22%5D%0A%20%20INS%5B%22%E6%8F%92%E5%85%A5%22%5D%20--%3E%20KICK%5B%22%E8%B8%A2%E6%8C%87%E7%BA%B9%E5%88%B0%E5%8F%A6%E4%B8%80%E6%A1%B6%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 Bloom：\\(k\\) 个独立位 vs 两桶指纹。布谷过滤器缓存局部性更好（查两桶），同空间下假阳性常更优（论文实验），本课用机制说话不抄表。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"另一桶必须由当前桶与 fp 算出，故不能只存无法反推的索引。负载因子过高踢失败，要留空。假阴性：标准正确实现查找不应假阴；误删造成假阴，删除须应用层保证「曾插入」。",-1)),(E(),s(n,null,{default:o(()=>[B(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E6%8F%92%E5%85%A5%E6%8C%87%E7%BA%B9%20fp%22%5D%20--%3E%20C1%7B%22%E6%A1%B6%20h1%20%E6%9C%89%E7%A9%BA%E4%BD%8D%EF%BC%9F%22%7D%0A%20%20C1%20--%3E%7C%22%E6%9C%89%22%7C%20P1%5B%22%E7%9B%B4%E6%8E%A5%E6%94%BE%E5%85%A5%20h1%22%5D%0A%20%20C1%20--%3E%7C%22%E6%BB%A1%22%7C%20C2%7B%22%E5%8F%A6%E4%B8%80%E5%80%99%E9%80%89%E6%A1%B6%E6%9C%89%E7%A9%BA%E4%BD%8D%EF%BC%9F%22%7D%0A%20%20C2%20--%3E%7C%22%E6%9C%89%22%7C%20P2%5B%22%E6%94%BE%E5%85%A5%E5%8F%A6%E4%B8%80%E5%80%99%E9%80%89%E6%A1%B6%22%5D%0A%20%20C2%20--%3E%7C%22%E6%BB%A1%22%7C%20K%5B%22%E8%B8%A2%E5%87%BA%E6%A1%B6%E5%86%85%E4%B8%80%E6%9E%9A%E6%97%A7%E6%8C%87%E7%BA%B9%22%5D%0A%20%20K%20--%3E%20RE%5B%22%E6%97%A7%E6%8C%87%E7%BA%B9%E8%90%BD%E5%88%B0%E5%AE%83%E8%87%AA%E5%B7%B1%E7%9A%84%E5%8F%A6%E4%B8%80%E5%B7%A2%22%5D%0A%20%20RE%20--%3E%20LIM%5B%22%E8%B8%A2%E9%93%BE%E8%BF%87%E9%95%BF%EF%BC%9A%E6%89%A9%E5%AE%B9%E6%88%96%E5%88%A4%E5%A4%B1%E8%B4%A5%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p><span class="marginnote">数字实例：每桶 4 槽、负载冲到 95% 附近时，新指纹几乎插不进去，踢链会越长越长；工程上常把负载留在 85% 以下。Bloom 没有这条纪律——它没有&quot;桶满&quot;的概念，这正是布谷为可删除付出的代价。</span></p><p>商过滤器下一课用商+余数紧排，另一套可删近似集。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给对抗构造去刷误删。不把 CoNEXT 图表当正文。精确字典请回完美散列或 HAMT。</p><p>后课默认：可删近似成员可用布谷过滤器。紧凑商+余数布局用商过滤器。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>布谷过滤器：指纹 + 两巢踢人，可删。</li><li>假阳性由指纹长与负载决定。</li><li>下一课商过滤器换布局。</li><li>出处：Fan et al., <em>CoNEXT</em>, 2014；Pagh and Rodler。</li></ul>',7))])}const k=i(p,[["render",c]]);export{_ as __pageData,k as default};
